  "Reciprocity": {"Explanation": "The email offers a recommendation for a mortgage loan at a lower interest rate and asks the recipient to apply online by clicking a link, implying that the recipient has already been approved and will receive benefits in return."},
  "Scarcity": {"Explanation": "The email creates a sense of urgency by implying that the recipient is already approved and that applying quickly will result in less paperwork, but it does not explicitly state a limited time or quantity."},
  "Authority": {"Explanation": "The email claims credibility through the title of the sender, 'Personal Broker', but does not display a recognized institution or title."},
  "Commitment/Consistency": {"Explanation": "The email references the recipient's previous mortgage loan and implies that they have already made a choice to work with the company, but does not explicitly state their previous behavior or choices."},
  "Liking": {"Explanation": "The email uses a personal greeting and a personal name, 'Kyle Sterling', to build a rapport with the recipient."},
  "Social proof": {"Explanation": "The email does not explicitly reference other people's participation or endorsement, but the use of a title and a personal name may imply a level of professionalism and trustworthiness."}
}

