  "Reciprocity": {
    "Explanation": "The email offers the recipient a chance to become the guardian and help the sender with investing money in the recipient's country, and in return, the sender will provide the recipient with information, procedures, amount involved, and mutually agree on the recipient's percentage interest or shareholding. This is an example of reciprocity, where the sender offers something and asks for a favor in return."
  },
  "Scarcity": {
    "Explanation": "The email creates urgency by implying limited time, as the sender asks the recipient to give the matter immediate attention and provide an urgent reply today. This creates a sense of scarcity and encourages the recipient to act quickly."
  },
  "Authority": {
    "Explanation": "Not present. There is no indication of authority or credibility through a recognized institution, title, or role in the email."
  },
  "Commitment/Consistency": {
    "Explanation": "Not present. There is no reference to prior behavior or choices of the recipient that the sender is trying to build upon."
  },
  "Liking": {
    "Explanation": "Not present. There is no attempt to build trust or rapport through familiarity, flattery, or personalization."
  },
  "Social proof": {
    "Explanation": "Not present. There is no reference to other people's participation or endorsement that would support the legitimacy of the proposal."
  }
}

